def check_cells(cells):
    """校验 (名称, 数量) 单元格：名称空 -> "no name"；数量<0 -> "neg qty"。
    返回所有违规 (行号, 原因) 列表；全部合法返回 []。"""
    problems = []
    for i, (name, qty) in enumerate(cells):
        if name == "":
            return [(i, "no name")]
        if qty < 0:
            return [(i, "neg qty")]
    return problems

