from target import check_cells

def test_all_ok():
    assert check_cells([("pen", 3), ("book", 0)]) == []

def test_one_bad():
    assert check_cells([("pen", 3), ("", 1)]) == [(1, "no name")]

def test_collect_all():
    assert check_cells([("", -1), ("pen", 2), ("", 4)]) == [
        (0, "no name"), (2, "no name")]
